import React, { useState, useEffect } from 'react';
import { FaGithub, FaLinkedin, FaDownload } from 'react-icons/fa';

const Hero = () => {
  const [text, setText] = useState('');
  const [index, setIndex] = useState(0);
  const roles = ['Data Analyst', 'SQL Expert', 'Power BI Developer', 'Python Programmer'];
  
  useEffect(() => {
    let currentIndex = 0;
    let currentText = '';
    let isDeleting = false;
    
    const type = () => {
      const fullText = roles[currentIndex % roles.length];
      
      if (isDeleting) {
        currentText = fullText.substring(0, currentText.length - 1);
      } else {
        currentText = fullText.substring(0, currentText.length + 1);
      }
      
      setText(currentText);
      
      if (!isDeleting && currentText === fullText) {
        setTimeout(() => {
          isDeleting = true;
        }, 2000);
      } else if (isDeleting && currentText === '') {
        isDeleting = false;
        currentIndex++;
      }
      
      setTimeout(type, isDeleting ? 100 : 150);
    };
    
    type();
  }, []);
  
  const handleDownload = () => {
    // Create a download link for the resume
    const link = document.createElement('a');
    link.href = '/resume.pdf';
    link.download = 'Anand_Resume.pdf';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };
  
  return (
    <section id="home" className="min-h-screen flex items-center justify-center pt-16 bg-gradient-to-br from-black via-gray-900 to-black">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20">
        <div className="text-center">
          <h1 className="text-5xl md:text-7xl font-bold mb-6 bg-gradient-to-r from-purple-500 via-pink-500 to-red-500 bg-clip-text text-transparent animate-gradient">
            Anand Kumar
          </h1>
          <div className="text-2xl md:text-3xl mb-8 h-16">
            <span className="text-gray-300">I'm a </span>
            <span className="text-purple-500 font-semibold">{text}</span>
            <span className="animate-pulse">|</span>
          </div>
          <p className="text-gray-400 text-lg mb-12 max-w-2xl mx-auto">
            Passionate data analyst skilled in SQL, Python, Power BI, and Excel. 
            Transforming complex data into actionable insights to drive business decisions.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <button
              onClick={handleDownload}
              className="inline-flex items-center gap-2 px-8 py-3 bg-gradient-to-r from-purple-500 to-pink-500 text-white rounded-full hover:shadow-lg hover:shadow-purple-500/50 transition-all duration-300 transform hover:scale-105"
            >
              <FaDownload />
              Download Resume
            </button>
            <a
              href="#contact"
              className="inline-flex items-center gap-2 px-8 py-3 border-2 border-purple-500 text-purple-500 rounded-full hover:bg-purple-500 hover:text-white transition-all duration-300"
            >
              Contact Me
            </a>
          </div>
          <div className="flex gap-6 justify-center mt-12">
            <a
              href="https://github.com/anand-kumar"
              target="_blank"
              rel="noopener noreferrer"
              className="text-gray-400 hover:text-purple-500 transition-colors duration-300 text-2xl"
            >
              <FaGithub />
            </a>
            <a
              href="https://linkedin.com/in/anand-kumar"
              target="_blank"
              rel="noopener noreferrer"
              className="text-gray-400 hover:text-purple-500 transition-colors duration-300 text-2xl"
            >
              <FaLinkedin />
            </a>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Hero;
